import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"師貞","description":"周易集解 - 師貞","frontmatter":{"title":"師貞","description":"周易集解 - 師貞"},"headers":[],"relativePath":"classics/jijie/007.md","filePath":"classics/jijie/007.md"}'),l={name:"classics/jijie/007.md"};function p(n,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="師貞" tabindex="-1">師貞 <a class="header-anchor" href="#師貞" aria-label="Permalink to “師貞”">​</a></h1><h2 id="師貞-1" tabindex="-1">師貞 <a class="header-anchor" href="#師貞-1" aria-label="Permalink to “師貞”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>師貞，丈人吉，無咎。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：訟必有眾起，故受之以師，師者眾也。</p><p>崔憬曰：因爭必起眾相攻，故受之以師也。</p><p>何晏曰：師者，軍旅之名。故《周禮》雲：二千五百人為師也。</p><p>王弼曰：丈人，嚴莊之稱，有軍正者也。為師之正，丈人乃吉。興役動眾，無功則罪，故吉乃無咎。</p><p>陸績曰：丈人者，聖人也。帥師未必聖人，若漢高祖、光武應此義也。</p><p>崔憬曰：《子夏傳》作大人，竝王者之師也。</p><p>案：此《彖》雲：師眾，貞正也。能以眾正，可以王矣。故《老子》曰：「域中有四大，而王居其一焉。」由是觀之，則知夫為王者，必大人也，豈以丈人而為王哉！故《乾．文言》曰：「夫大人與天地合德，與日月合明，先天而天不違，後天而奉天時，天且不違，而況於人乎！」況於行師乎！以斯而論，《子夏傳》作大人，是也。今王氏曲解大人為丈人，臆雲「嚴莊之稱」，學不師古，匪說攸聞，既誤違於經旨，輒改正作大人明矣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：師眾也，貞正也。能以眾正，可以王矣。剛中而應，行險而順，以此毒天下，而民從之，吉又何咎矣。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>虞翻曰：坤為眾，謂二失位，變之五，為比故能以眾正，乃可以王矣。</p><p>荀爽曰：謂二有中和之德，而據群陰，上居五位，可以王也。</p><p>蜀才曰：此本剝卦。</p><p>案：上九降二，六二升上，是剛中而應，行險而順也。</p><p>乾寶曰：坎為險，坤為順，兵革刑獄，所以險民也。毒民於險中，而得順道者，聖王之所難也。毒，荼，苦也。五刑之用，斬刺肌體，六軍之鋒，殘破城邑，皆所以荼毒姦兇之人，使服王法者也。故曰「以此毒天下而民從之」。毒以治民，明不獲已而用之，故於彖象六爻，皆著戒懼之辭也。</p><p>崔憬曰：剛能進義，中能正眾，既順且應，行險戡暴，亭毒天下，人皆歸往而以為王，吉又何咎矣。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：地中有水，師。君子以容民畜眾。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>陸績曰：坎在坤內，故曰地中有水。師，眾也。坤中眾者，莫過於水。</p><p>虞翻曰：君子謂二。容，寬也。坤為民眾，又畜養也。陽在二，寬以居之，五變執言時，有頤養象。故以容民畜眾矣。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，師出以律，否臧兇。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：師出以律，失律兇也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>案：初六以陰居陽，履失其位，位既匪正，雖令不從。以斯行師，失律者也。凡首率師出必以律，若不以律，雖臧亦兇。故曰「師出以律，失律兇也」。</p><p>《九家易》曰：坎為法律也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，在師中，吉，無咎。王三錫命。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：在師中吉，承天寵也。王三錫命，懷萬邦也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：雖當為王，尚在師中，為天所寵，事克功成。故吉無咎。二非其位，蓋謂武王受命而未即位也。受命為王，定天下以師。故曰在師中吉。</p><p>荀爽曰：王謂二也。三者，陽德成也。德純道盛，故能上居王位，而行錫命，群陰歸之。故曰「王三錫命，懷萬邦也」。</p><p>案：二互體震，震木。數三，王三錫命之象。《周禮》雲：一命受職，再命受服，三命受位，是其義也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，師或輿屍，兇。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：坤為屍，坎為車多眚。同人離為戈兵，為折首。失位乘剛無應，屍在車上，故輿屍兇矣。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：師或輿屍，大無功也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>盧氏曰：失位乘剛，內外無應，以此帥師必大敗。故有輿屍之兇，功業大喪也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，師左次，無咎。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>荀爽曰：左謂二也，陽稱左。次，舍也。二與四同功，四承五，五無陽，故呼二舍於五，四得承之，故無咎。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：左次無咎，未失常也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>崔憬曰：偏將軍居左。左次，常備師也。師順用柔，與險無應，進取不可，次舍無咎，得位故也。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，田有禽，利執言，無咎。長子帥師，弟子輿屍，貞兇。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：田謂二。陽稱禽。震為言。五失位，變之正，艮為執。故利執言無咎。</p><p>荀爽曰：田，獵也。謂二帥師禽五，五利度二之命，執行其言，故無咎也。</p><p>案：六五居尊失位，在師之時，蓋由殷紂而被武王擒於鹿臺之類是也。以臣伐君，假言田獵。六五離爻，體坤，離為戈兵，田獵行師之象也。</p><p>虞翻曰：長子謂二，震為長子，在師中，故帥師也。</p><p>虞翻曰：弟子謂三。三體坎。坎震之弟而乾之子，失位乘陽，逆，故貞兇。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：長子帥師，以中行也。弟子輿屍，使不當也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：長子謂九二也。五處中應二，受任帥師，當上升五。故曰「長子帥師，以中行也」。</p><p>宋衷曰：弟子謂六三也。失位乘陽，處非所據。眾不聽從，師人分北，或敗績死亡，輿屍而還，故曰弟子輿屍。謂使不當其職也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，大君有命，開國承家，小人勿用。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：同人，乾為大君，巽為有命。</p><p>乾寶曰：大君，聖人也。有命，天命也。五常為王位，至師之家，而變其例者。上為郊也，故易位以見武王親徵與師，人同處於野也。離上九曰：王用出徵，有嘉折首。上六為宗廟，武王以文王行，故正開國之辭於宗廟之爻，明己之受命，文王之德也。故《書．泰誓》曰：予克紂，非予武，惟朕文考無罪。受克予，非朕文考有罪，惟予小子無良。開國，封諸侯也。承家，立都邑也。小人勿用，非所能矣。</p><p>虞翻曰：承，受也。坤為國。二稱家。謂變乾為坤，欲令二上居五，為比，故開國承家。</p><p>荀爽曰：大君，謂二。師旅已息，既上居五，當封賞有功，立國命家也。開國，封諸侯。承家，立大夫也。</p><p>宋衷曰：陽當之五，處坤之中，故曰開國。陰下之二，在二承五，故曰承家。開國，謂析土地以封諸侯，如武王封周公七百裡地也。承家，立大夫，為差次，立大夫。因采地名，正其功勳，行其賞祿。</p><p>虞翻曰：陰稱小人，坤虛無君，體迷復兇，坤成乾滅，以弒君，故小人勿用。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：大君有命，以正功也。小人勿用，必亂邦也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：謂五多功，五動正位，故正功也。</p><p>乾寶曰：湯武之事。</p><p>虞翻曰：坤反君道，故亂邦也。</p><p>乾寶曰：楚靈、齊閔，窮兵之禍也。</p>',87)])])}const m=e(l,[["render",p]]);export{b as __pageData,m as default};
